private static int parseEndOfLine(String headerPart, int end) {
    // Loop until we find the \r\n sequence
    while (end < headerPart.length()) {
        if (headerPart.charAt(end) == '\r') {
            end++;
            if (end == headerPart.length()) {
                // Found \r at the end of the string, which means the remainder is empty, so just return end
                return end;
            }
            if (headerPart.charAt(end) == '\n') {
                // Found \r\n sequence, so return end + 1
                return end + 1;
            }
            // Found \r, but not followed by \n, so throw an exception
            throw new IllegalStateException("Invalid header format");
        }
        end++;
    }
    // Reached the end of the string without finding \r\n, so just return end
    return end;
}

