    Set<V> leftSet = new HashSet<>();
    Set<V> rightSet = new HashSet<>();

    // Iterate over all elements in the result map
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        // If the value is in the left side, add it to the left set
