private long readLong(int offset) {
    // Check if the offset is valid
    if (offset < 0 || offset > data.length - 8) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }

    // Read the long value from the byte array
    long value = data[offset] & 0xffL;
    value |= (data[offset + 1] & 0xffL) << 8;
    value |= (data[offset + 2] & 0xffL) << 16;
    value |= (data[offset + 3] & 0xffL) << 24;
    value |= (data[offset + 4] & 0xffL) << 32;
    value |= (data[offset + 5] & 0xffL) << 40;
    value |= (data[offset + 6] & 0xffL) << 48;
    value |= (data[offset + 7] & 0xffL) << 56;

    return value;
}

