protected List<TimeRange> buildTimeRanges(long start, long end) {
  List<TimeRange> ranges = new ArrayList<>();
  long duration = FETCH_DATA_DURATION;
  while (start < end) {
    long rangeStart = start;
    long rangeEnd = Math.min(duration, end);
    ranges.add(new TimeRange(rangeStart, rangeEnd));
    start += rangeEnd;
  }
  return ranges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    // Split time ranges to insure the start time and end time is small then 1 hour
    long step = FETCH_DATA_DURATION;
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = currentStart + step;
        if (currentEnd > end) {
            currentEnd = end;
        }
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd + 1;
    }
    return timeRanges;
}

private List<TimeRange> buildTimeRanges(long start, long end) {
    // Split time ranges to insure the start time and end time is small then {@link #FETCH_DATA_DURATION}
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;
    if (start <= duration && end <= duration) {
        timeRanges.add(new TimeRange(start, end));
        return timeRanges;
    }
    long startTime = start;
    while (startTime <= end) {
        long endTime = Math.min(startTime + duration, end);
        timeRanges.add(new TimeRange(startTime, endTime));
        startTime = endTime + 1;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long diff = end - start;
    long maxTimeRange = FETCH_DATA_DURATION;
    long startTime = start;
    long endTime = 0;

    while (diff > 0) {
        if (diff >= maxTimeRange) {
            endTime = startTime + maxTimeRange;
            timeRanges.add(new TimeRange(startTime, endTime));
            startTime = endTime;
            diff = diff - maxTimeRange;
        } else {
            endTime = startTime + diff;
            timeRanges.add(new TimeRange(startTime, endTime));
            break;
        }
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long startTime, long endTime) {
    // Check if the time range is small enough to be fetched in a single request
    if (endTime - startTime <= FETCH_DATA_DURATION) {
        return Collections.singletonList(new TimeRange(startTime, endTime));
    }

    // Calculate the number of time ranges needed to split the time range
    int numRanges = (int) Math.ceil((endTime - startTime) / (double) FETCH_DATA_DURATION);

    // Split the time range into smaller time ranges
    List<TimeRange> timeRanges = new ArrayList<>(numRanges);
    long currentStart = startTime;
    for (int i = 0; i < numRanges; i++) {
        long currentEnd = currentStart + FETCH_DATA_DURATION;
        if (currentEnd > endTime) {
            currentEnd = endTime;
        }
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd + 1;
    }

    return timeRanges;
}

