static long compressTimeBucket(long timeBucket, int dayStep) {
    SimpleDateFormat sdf = new SimpleDateFormat("yyyyMMdd");
    sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
    int compressStep = (int) Math.pow(10, 1 - dayStep);
    Date date = new Date(timeBucket * 1000);
    String formattedDate = sdf.format(date);
    String[] parts = formattedDate.split("");
    int year = Integer.parseInt(parts[0] + parts[1] + parts[2] + parts[3]);
    int month = Integer.parseInt(parts[4] + parts[5]);
    int day = Integer.parseInt(parts[6] + parts[7]);
    int newYear = year / compressStep;
    int newMonth = month / compressStep;
    int newDay = day / compressStep;
    if (newDay < 10) {
        newDay = 10;
    }
    if (newMonth < 10) {
        newMonth = 10;
    }
    if (newYear < 10) {
        newYear = 10;
    }
    return sdf.parse(newYear + "" + newMonth + "" + newDay + "0000").getTime() / 1000;
}

