boolean endsWith(String str, String suffix, boolean ignoreCase) {
  // If the String is null, return false
  if (str == null) {
    return false;
  }

  // If the suffix is null, return true
  if (suffix == null) {
    return true;
  }

  // Get the length of the String and the suffix
  int strLength = str.length();
  int suffixLength = suffix.length();

  // If the suffix is longer than the String, return false
  if (suffixLength > strLength) {
    return false;
  }

  // Get the starting index of the suffix in the String
  int suffixStartIndex = strLength - suffixLength;

  // If the suffix is already at the end of the String, return true
  if (suffixStartIndex == 0) {
    return true;
  }

  // If the suffix is not case-insensitive, return true if the suffix starts with the String
  if (!ignoreCase) {
    return str.substring(suffixStartIndex).equals(suffix);
  }

  // If the suffix is case-insensitive, return true if the suffix starts with the String after converting both to lowercase
  return str.substring(suffixStartIndex).equalsIgnoreCase(suffix);
}

