        str = str.toLowerCase();
        suffix = suffix.toLowerCase();
    }

    return str.endsWith(suffix);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Check if the URI is valid
    if (u == null) {
        throw new IllegalArgumentException("u cannot be null");
    }

    // Get the path component of the URI
    String path = u.getPath();

    // Check if the path component is an absolute path component
    if (path.startsWith("/")) {
        // Remove the leading '/'
        path = path.substring(1);
    }

    // Split the path component into path segments
    String[] segments = path.split("/");

    // Create a list to hold the decoded path segment
    List<PathSegmentImpl> decodedSegments = new ArrayList<>();

    // Iterate over the path segments
    for (String segment : segments) {
        // Decode the path segment if requested
        if (decode) {
            segment = URLDecoder.decode(segment, "UTF-8");
        }

        // Add the decoded path segment to the list
        decodedSegments.add(new PathSegmentImpl(segment));
    }

    // Return the list of decoded path segments
    return decodedSegments;
}

static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String[] segments = u.getPath().split("/");

    for (int i = 0; i < segments.length; i++) {
        String segment = segments[i];
        if (segment.isEmpty() && i != 0) {
            // Skip empty segments.
            continue;
        }
        if (decode && !segment.startsWith("/")) {
            // Use the decoded form if required.
            segment = UriDecoder.decode(segment, StandardCharsets.UTF_8);
        }
        // Use the raw form if not required.
        PathSegmentImpl pathSegment = new PathSegmentImpl(segment);
        pathSegments.add(pathSegment);
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String[] pathSegmentsStr = u.getPath().split("/");
    for (String segment : pathSegmentsStr) {
        if (decode) {
            segment = URLDecoder.decode(segment, "UTF-8");
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }
