public static List<PathSegmentImpl> decodePath(final URI u, final boolean decode) {
    // Check the input parameters
    if (u == null) {
        throw new IllegalArgumentException("u cannot be null");
    }

    // Extract the path component from the URI
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }

    // Skip the leading '/' if necessary
    int start = (path.charAt(0) == '/') ? 1 : 0;

    // Split the path component into path segments
    List<PathSegmentImpl> segments = new ArrayList<>();
    int end = start;
    while (end < path.length()) {
        end = path.indexOf('/', end);
        if (end == -1) {
            end = path.length();
        }
        String segment = path.substring(start, end);
        if (decode) {
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8);
        }
        segments.add(new PathSegmentImpl(segment));
        start = end + 1;
    }

    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u.getPathComponents() != null) {
        List<PathSegmentImpl> segments = new ArrayList<>();
        for (String segment : u.getPathComponents()) {
            PathSegmentImpl newSegment = new PathSegmentImpl(segment, decode);
            segments.add(newSegment);
        }
        return segments;
    } else {
        return Collections.emptyList();
    }
}

