    // Check if there are more files in the input stream
    if (inputStream.available() > 0) {
        // Create a new file object with the next available file name
        File file = new File(inputStream.nextFileName());

        // Check if the file exists and is a directory
        if (file.exists() && file.isDirectory()) {
            // Recursively call the next() method to get the next file
            return next();
        } else {
            // Open a new input stream for the file
