            break;
        case 'J':
            // Long type, pop a value
            long value = outputFrameStack.popLong();
            break;
        case 'F':
            // Float type, pop a value
            float value = outputFrameStack.popFloat();
            break;
        case 'D':
            // Double type, pop a value
            double value = outputFrameStack.popDouble();
            break;
        case 'L':
            // Object type, pop a reference
            Object value = outputFrameStack.popReference();
            break;
        default:
            throw new IllegalStateException("Unexpected type encountered in pop: " + descriptor);
    }
}

