public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
	// Calculate the middle point along the x-axis
	Vector2D middle = box.getMiddlePoint().add(new Vector2D(box.getWidth() / 2, 0));

	// Create two new boxes, one with the half of the original width on each side of the middle point
	Box2D leftBox = new Box2D(new Vector2D(box.getX(), box.getY()), middle);
	Box2D rightBox = new Box2D(middle, new Vector2D(box.getX() + box.getWidth(), box.getY() + box.getHeight()));

	return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    float halfWidth = box.width / 2;
    float x1 = box.x + halfWidth;
    float x2 = x1 + halfWidth;

    Box2D leftBox = new Box2D(box.x, box.y, x1, box.y + box.height);
    Box2D rightBox = new Box2D(x2, box.y, box.x + box.width, box.y + box.height);

    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Check that the box is non-empty and has a valid width
    if (box.getWidth() <= 0) {
        throw new IllegalArgumentException("Box has invalid width");
    }

    // Calculate the new width of each half box
    double halfWidth = box.getWidth() / 2;

    // Create two new boxes, one each for the left and right half
    Box2D leftHalfBox = new Box2D(box.getMinX(), box.getMinY(), halfWidth, box.getHeight());
    Box2D rightHalfBox = new Box2D(box.getMinX() + halfWidth, box.getMinY(), halfWidth, box.getHeight());

    // Return the pair of boxes
    return Pair.of(leftHalfBox, rightHalfBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis( Box2D box ) {

    // calculate the x coordinate of the midpoint
    float midpointX = (box.x + box.z) / 2;

    // create two new boxes with the appropriate x coordinates
    Box2D leftBox = new Box2D( box.x, box.y, midpointX );
    Box2D rightBox = new Box2D( midpointX, box.y, box.z );

    return new Pair<>( leftBox, rightBox );
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    float halfWidth = box.getWidth() / 2;
    Box2D leftBox = new Box2D(box.getLeft(), box.getBottom(), halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(box.getLeft() + halfWidth, box.getBottom(), box.getWidth() - halfWidth, box.getHeight());
    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

