private void putAbstractTypes(int start, int end) {
    // Loop through the abstract types in the current frame, starting from "start" and ending at "end"
    for (int i = start; i < end; i++) {
        // Get the abstract type at the current index
        Object abstractType = currentFrame.abstractTypes[i];

        // Check if the abstract type is a reference
        if (abstractType instanceof IUninitializedReference) {
            // If so, add it to the stack map table entries
            stackMapTableEntries.add(new StackMapFrame.AbstractTypeImmediate(new VerificationTypeInfo.UninitializedType((IUninitializedReference) abstractType)));
        } else if (abstractType instanceof IKlass) {
            // If not, check if it's a klass
            IKlass klass = (IKlass) abstractType;
            if (klass.isReference()) {
                // If it is a reference type, add it to the stack map table entries
                stackMapTableEntries.add(new StackMapFrame.AbstractTypeImmediate(new VerificationTypeInfo.ObjectType(klass.getKlass())));
            } else if (klass.isPrimitiveType()) {
                // If it's a primitive type, add it to the stack map table entries
                stackMapTableEntries.add(new StackMapFrame.AbstractTypeImmediate(VerificationTypeInfo.forPrimitiveType(klass.getPrimitiveType())));
            } else {
                // If it's neither a reference or a primitive type, add it as a new type with module set to null
                stackMapTableEntries.add(new StackMapFrame.AbstractTypeImmediate(new VerificationTypeInfo.NewType(klass.getKlass(), null)));
            }
        } else {
            // If it's not a reference or a klass, it's a uninitialized type, add it to the stack map table entries
            stackMapTableEntries.add(new StackMapFrame.AbstractTypeImmediate(new VerificationTypeInfo.UninitializedType(abstractType)));
        }
    }
}

private void putAbstractTypes(int start, int end) {
    // Iterate over abstract types in the current frame
    for (int i = start; i < end; i++) {
        AbstractType abstractType = currentFrame.getAbstractType(i);
        // Check if the type is uninitialized This is not covered in the original implementation, but
        // it is a possibility that could arise when dealing with uninitialized types.
        if (abstractType instanceof UninitializedType) {
            // If the type is uninitialized, put the index of the local variable that holds it
            // in the StackMapTable attribute.
            int uninitializedIndex = ((UninitializedType) abstractType).getUninitializedLocalVariable().getIndex();
            stackMapTableEntries.put(new PipeWriter.池.Wrapper().forCustom(VERIFICATION_TYPE_IN_STACK_MAP_TABLE_TAG_ITEM)
                    .putUShort(uninitializedIndex).putByte(ITEM_UNINIT));
        } else {
            // Otherwise, put the verification_type_info of the abstract type.
            abstractType.putKlass(this);
        }
    }
}

