void putAbstractTypes(int start, int end) {
	for (int i = start; i < end; i++) {
		VerificationTypeInfo vti = currentFrame.get(i);

		// Inferred type info is used when the type is not fully declared or is a primtive type
		if (vti.isInferred()) {
			stackMapTableEntries.add(new InferredTypeInfo());
		} else if (vti.isPrimitive()) { // Primitive type
			PrimitiveType primitiveType = vti.getPrimitiveType();
			switch (primitiveType) {
				case BYTE:
				case CHAR:
				case SHORT:
				case INT:
					stackMapTableEntries.add(new SameLocals1StackItemFrame(new VerificationTypeInfo.UninitializedThis()));
					break;
				case BOOLEAN:
				case FLOAT:
				case DOUBLE:
				case LONG:
					stackMapTableEntries.add(new SameLocals1StackItemFrame(new VerificationTypeInfo.ObjectVariableInfo(i, true, null)));
					break;
			}
		} else { // Non-primitive type
			stackMapTableEntries.add(new SameLocals1StackItemFrame(new VerificationTypeInfo.ObjectVariableInfo(i, false, null)));
		}
	}
