public static Object[] copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
	// Check input
	if (array == null) {
		throw new IllegalArgumentException("Input array cannot be null");
	}
	if (newArrayComponentType == null) {
		throw new IllegalArgumentException("New array component type cannot be null");
	}

	// Get array length and create new array
	int oldArrayLength = Array.getLength(array);
	Object newArray = Array.newInstance(newArrayComponentType, oldArrayLength + 1);

	// Copy elements from old array to new array
	for (int i = 0; i < oldArrayLength; i++) {
		Array.set(newArray, i, Array.get(array, i));
	}

	// Return new array
	return (Object[]) newArray;
