protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize a graph path with an empty sequence of edges
    GraphPath<V, E> gp = new GraphPath<>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the source and target vertices of the edge
        V src = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the graph path, using the source and target vertices
        gp.addEdge(edge, src, target);
    }

    // Return the constructed graph path
    return gp;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Build a stack to store the edges of the tour
    Stack<E> edgeStack = new Stack<>();

    // Iterate through the edges of the tour
    for (E edge : tour) {
        // Add the edge to the stack
        edgeStack.push(edge);
    }

    // Create a graph path
    GraphPath<V, E> path = new GraphPath<V, E>(graph);

    // Use the stack to add the edges to the path
    while (!edgeStack.isEmpty()) {
        // Get the next edge
        E edge = edgeStack.pop();

        // Get the start and end vertices of the edge
        V start = edge.getStart();
        V end = edge.getEnd();

        // Add the edge to the path
        path.addEdge(edge);

        // Add the vertices to the path
        path.addVertex(start);
        path.addVertex(end);

        // If the start vertex is not the end vertex, add its neighbors to the stack
        if (!start.equals(end)) {
            edgeStack.addAll(graph.getNeighbors(start));
        }
    }

    // Return the path
    return path;
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path with the first edge in the tour
    GraphPath<V, E> path = new GraphPath<V, E>(graph, tour.iterator().next());

    // Set the last node in the tour as the initial node in the path
    V currentNode = path.getEndVertex();

    // Iterate through the remaining edges in the tour
    for (E edge : tour) {
        // Get the next node in the tour
        V nextNode = graph.getEdgeTarget(edge);

        // Add the edge to the path
        path.addEdge(edge);

        // Set the last node in the path to the next node
        path.setEndVertex(nextNode);

        // Update the last node in the path
        currentNode = nextNode;
    }

    // Return the completed graph path
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize the graph path with the first edge
    GraphPath<V,E> path = new GraphPath<V,E>(graph, tour.iterator().next());

    // Add the remaining edges to the path
    for (E edge : tour) {
        path.addEdge(edge);
    }

    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    List<V> vertices = new ArrayList<>();
    for (E edge : tour) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }

    return new GraphPathImpl<>(graph, vertices);
}

