public String unescapeId(String input) {
    // Use a StringBuilder to build the unescaped output
    // since we don't know the final length in advance
    StringBuilder sb = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);

        // If the character is a backslash, check the next character
        if (c == '\\') {
            // If the next character is a valid escape sequence, convert and add it to the output
            if (i + 1 < input.length() && input.charAt(i + 1) == '!' || input.charAt(i + 1) == '\'') {
                sb.append(input.charAt(i + 1));
            }
        } else {
            // Add the character to the output
            sb.append(c);
        }
    }

    // Return the unescaped output
    return sb.toString();
}

