public void removeSelf() {

    // First, check if the bucket has a parent bucket
    if (parent != null) {

        // If it does, get its reference count
        int refCount = parent.getRefCount();

        // Decrease the reference count by 1
        refCount--;

        // If the reference count is 0, remove the bucket from the parent
        if (refCount == 0) {

            // Remove the bucket from the parent
            parent.removeChild(this);

        } else {

            // Otherwise, update the parent's reference count
            parent.setRefCount(refCount);
        }
    }

    // Remove the bucket from this bucket's reference map
    referenceMap.remove(this);
}

