boolean function (ListNodeImpl<E> node) {
    // Check if the node is in the list
    if (node == null || node.next != null || node.previous != null) {
        return false;
    }

    // If the node is the head or tail, remove it
    if (node == head) {
        head = node.next;
    }
    if (node == tail) {
        tail = node.previous;
    }

    // Update the pointers of the adjacent nodes
    node.next.previous = node.previous;
    node.previous.next = node.next;
    node.next = node.previous = null;
    size--;

    return true;
}

boolean function (ListNodeImpl<E> node) {
    // Check if the head of the list is the node to unlink
    if (node == head) {
        head = node.next;
    } else {
        // Find the previous node in the list
        ListNodeImpl<E> prev = head;
        while (prev.next != node) {
            prev = prev.next;
        }
        // Unlink the node
        prev.next = node.next;
    }
    // Decrement the size of the list
    size--;
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node.getPrevious() != null) {
        node.getPrevious().setNext(node.getNext());
    }
    if (node.getNext() != null) {
        node.getNext().setPrevious(node.getPrevious());
    }
    // set the previous and next pointers of the node to null
    node.setPrevious(null);
    node.setNext(null);
    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    // Check if the given node is null
    if (node == null) {
        return false; // No need to remove a null node
    }

    // Find the previous node of the given node
    ListNodeImpl<E> prev = findPrevious(node);

    // Remove the given node from the list
    if (prev != null) {
        prev.unlink(node);
        return true;
    }

    return false;
}

