    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;

    // Iterate over the bounds list from the end to the start
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add((int) sum);
    }

    // Return a pair containing the suffix sum list and the sum of all elements
    return new Pair<>(suffixSum, sum);
}

