    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // Loop through the bounds list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Get the current bound
        int bound = bounds.get(i);

        // Add the bound to the total sum
        totalSum += bound;

        // Add the bound to the suffix sum list
        suffixSum.add(bound);
    }

    // Return the computed suffix sum and the total sum
    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computePrefixSum(List<Integer> bounds){
