    List<Integer> prefixSum = new ArrayList<>();
    long totalSum = 0;

    // Loop through the bounds list
    for (int bound : bounds) {
        // Add the bound to the total sum
        totalSum += bound;

        // Add the bound to the prefix sum list
        prefixSum.add(bound);
    }

    // Return the computed prefix sum and the total sum
    return new Pair<>(prefixSum, totalSum);
}

