public static final <V>void reverse(V[] arr, int from, int to) {
    // Check if the specified range is valid
    if (from < 0 || to < 0 || from > to || from >= arr.length || to >= arr.length) {
        throw new IndexOutOfBoundsException("Invalid range specified: from=" + from + ", to=" + to + ", length=" + arr.length);
    }

    // Loop backwards from the end of the range to the beginning, swapping elements
    for (int i = to; i >= from; i--) {
        V tmp = arr[i];
        arr[i] = arr[from];
        arr[from] = tmp;
        from++;
    }
}

