    // Check if the range is valid
    if (from < 0 || to >= arr.length || from > to) {
      throw new ArrayIndexOutOfBoundsException("Invalid range specified");
    }

    // Reverse the range by iterating through both ends of the array
    // and swapping the elements
    for (int i = from, j = to; i < j; i++, j--) {
      V temp = arr[i];
      arr[i] = arr[j];
      arr[j] = temp;
    }
  }

public static final <V> void reverse(V[] arr, int from, int to) {
    if (from == to) {
      return;
    }

    int mid = (from + to) / 2;
    for (int i = from, j = to; i < mid; i++, j--) {
      V temp = arr[i];
      arr[i] = arr[j];
      arr[j] = temp;
    }

    reverse(arr, from, mid - 1);
    reverse(arr, mid, to);
  }

