public static Meteor lookup(HttpServletRequest r) {
    if (!(r instanceof MeteorRequest)) {
        return null;
    }

    MeteorRequest req = (MeteorRequest) r;
    String token = req.getToken();

    if (token == null) {
        return null;
    }

    // Look up the token in the cache
    Meteor result = null;
    Cache cache = getCache();
    if (cache.isEnabled()) {
        result = cache.get(token);
    }
    if (result != null) {
        return result;
    }

    // Get the user repository
    UserRepository repo = getUserRepository();

    // Look up the user
    User user = repo.getUser(token);

    // If the user was found, create a new Meteor instance
    if (user != null) {
        result = new Meteor(user);
        if (cache.isEnabled()) {
            cache.put(token, result);
        }
        return result;
    }

    return null;
}

