public void abbreviate(int nameStart, StringBuffer buf) {
    int nameLength = buf.length() - nameStart;
    if (nameLength <= 3) {
        return;
    }

    boolean enlarge = false;

    // Check for failed abbreviation
    if (nameLength > 4 && buf.charAt(nameStart) == 'D' && buf.charAt(nameStart + 1) == 'N' && buf.charAt(nameStart + 2) == 'S') {
        enlarge = true;
    }

    // Check for UNC
    if (!enlarge && nameLength > 2 && buf.charAt(nameStart) == '\\' && buf.charAt(nameStart + 1) == '\\') {
        enlarge = true;
    }

    // Check for round brackets
    int roundBracketIndex = buf.indexOf('(', nameStart);
    if (roundBracketIndex != -1) {
        roundBracketIndex = roundBracketIndex - nameStart;
        if (roundBracketIndex > 4 && buf.charAt(nameStart + roundBracketIndex - 2) == '(' && buf.charAt(nameStart + roundBracketIndex - 1) == ' ') {
            enlarge = true;
        }
    }

    if (enlarge) {
        buf.setLength(nameStart);
    }

    String abbreviation = buf.substring(nameStart, nameStart + 3);
    buf.setLength(nameStart);
    buf.append(abbreviation);
}

