public static Type resolveBound(TypeVariable<?> typeVariable){
    // Return the first bound that is not an upper bounded wildcard
    for(Type bound : typeVariable.getBounds()){
        if(!(bound instanceof WildcardType) || !((WildcardType) bound).getUpperBounds().isEmpty()){
            return bound;
        }
    }
    // No bound found, return Unknown.class
    return Unknown.class;
}

public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    // Check if the type variable has an explicit bound
    Type bound = typeVariable.getBound();
    if (bound != null) {
        return resolveType(bound);
    }

    // Check if the type variable is a type parameter of a generic declaration
    Type genericDeclaration = typeVariable.getGenericDeclaration();
    if (genericDeclaration instanceof Class<?>) {
        Class<?> declaringClass = (Class<?>) genericDeclaration;

        // Check if the declaring class has a type parameter with the same name as the type variable
        for (int i = 0; i < declaringClass.getTypeParameters().length; i++) {
            if (declaringClass.getTypeParameters()[i].equals(typeVariable)) {
                // Return the bound of the type parameter
                return declaringClass.getTypeParameters()[i].getBounds()[0];
            }
        }
    }

    // Return the class object for {@code java.lang.Object} if none can be resolved
    return Unknown.class;
}

private static Class<?> resolveType(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        return resolveType(((ParameterizedType) type).getRawType());
    } else if (type instanceof TypeVariable<?>) {
        return resolveBound((TypeVariable<?>) type);
    }

    // should never happen
    throw new IllegalArgumentException("Unknown type: " + type);
}

