    for (Type bound : bounds) {
        if (bound instanceof Class<?>) {
            resolvedType = bound;
            break;
        } else if (bound instanceof TypeVariable<?>) {
            resolvedType = resolveBound((TypeVariable<?>) bound);
            if (resolvedType != null) {
                break;
