private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    boolean[] visited = new boolean[graph.vertexSet().size()];
    for (V vertex : vertices) {
        if (!visited[graph.getVertexIndex(vertex)]) {
            visit(graph, vertex, visited);
        }
    }
    for (int i = 0; i < visited.length; i++) {
        if (!visited[i]) {
            return false;
        }
    }
    return true;
}

private static <V,E> void visit(Graph<V,E> graph, V vertex, boolean[] visited) {
    visited[graph.getVertexIndex(vertex)] = true;
    for (E edge : graph.outgoingEdgesOf(vertex)) {
        V neighbor = graph.getEdgeTarget(edge);
        if (!visited[graph.getVertexIndex(neighbor)]) {
            visit(graph, neighbor, visited);
        }
    }
}

