  List<Integer> upperBounds = new ArrayList<>(keys.size());

  // Iterate over the list of keys and compute the upper bound for each key
  for (K key : keys) {
    // Compute the minimum lower bound for the current key
    int upperBound = Math.min(lowerBound, key);

    // Add the upper bound to the list
