public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    // Remove any duplicate separators
    path = path.replaceAll("[/\\\\]+", "/");
    relativePath = relativePath.replaceAll("[/\\\\]+", "/");
    // If the relative path is absolute, just return it
    if (relativePath.startsWith("/")) {
        return relativePath;
    }
    // If the relative path is empty, just return the original path
    if (relativePath.isEmpty()) {
        return path;
    }
    // If the relative path starts with "..", remove the last segment of the original path
    if (relativePath.startsWith("..")) {
        path = path.substring(0, path.lastIndexOf('/'));
    }
    // Append the relative path to the original path
    return path + "/" + relativePath;
}

