public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Open the file for reading
    BufferedReader reader = new BufferedReader(new FileReader(file));

    // Skip the header
    String line = reader.readLine();
    if (line.startsWith("# Snapshot time")) {
        line = reader.readLine();
    }

    // Read each snapshot in the file
    while ((line = reader.readLine()) != null) {
        // Skip empty lines
        if (line.trim().isEmpty()) {
            continue;
        }

        // Split the line into parts
        String[] parts = line.split(":");
        if (parts.length > 7) {
            // Get the snapshot properties
            int id = Integer.parseInt(parts[0]);
            long timestamp = Long.parseLong(parts[1]);
            String snapshotName = parts[2];
            String md5sum = parts[3];
            String buildType = parts[4];
            String os = parts[5];
            String cpu = parts[6];

            // Check if the snapshot is within the time range
            TimeInterval timeInterval = TimeInterval.create(timestamp, snapshotName);
            if (timeRanges.stream().anyMatch(timeRange -> timeRange.isIncluded(timeInterval))) {
                // Add the snapshot to the list
                snapshots.add(new ThreadSnapshot(id, timestamp, snapshotName, md5sum, buildType, os, cpu));
            }
        }
    }

    // Close the file
    reader.close();

    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    // check if the file exists
    if (!file.exists()) {
        throw new FileNotFoundException("File does not exist: " + file.getName());
    }

    // check if the file is a valid JSON file
    if (!file.getName().endsWith(".json")) {
        throw new IOException("Not a valid JSON file: " + file.getName());
    }

    // read the JSON file
    String jsonString = new String(Files.readAllBytes(file.toPath()));
    JSONObject jsonObject = new JSONObject(jsonString);

    // parse the JSON object
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    JSONArray threads = jsonObject.getJSONArray("threads");
    for (int i = 0; i < threads.length(); i++) {
        JSONObject thread = threads.getJSONObject(i);
        long timestamp = thread.getLong("timestamp");
        long duration = thread.getLong("duration");
        JSONArray stackTraces = thread.getJSONArray("stackTraces");
        Set<ProfileAnalyzeTimeRange> matchingRanges = new HashSet<>();
        for (int j = 0; j < stackTraces.length(); j++) {
            JSONObject stackTrace = stackTraces.getJSONObject(j);
            long startTime = stackTrace.getLong("startTime");
            long endTime = stackTrace.getLong("endTime");
            if (TimeUtils.overlaps(startTime, endTime, timeRanges)) {
                matchingRanges.add(new ProfileAnalyzeTimeRange(startTime, endTime));
            }
        }
        if (!matchingRanges.isEmpty()) {
            ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, duration, matchingRanges);
            snapshots.add(snapshot);
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

// Check if the file exists and not empty
if (!file.exists() || file.length() == 0) {
    throw new IOException("File not found or empty: " + file.getAbsolutePath());
}

// Open a BufferedReader to read the contents of the file
try (BufferedReader br = new BufferedReader(new FileReader(file))) {

    // Iterate over the time ranges and parse the corresponding snapshots
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {

        // Skip to the start of the time range and read the snapshot
        br.skip(timeRange.getStartTime());
        ThreadSnapshot snapshot = ThreadSnapshot.parseFrom(br);

        // Add the snapshot to the list of snapshots
        snapshots.add(snapshot);
    }

    // Return the list of snapshots
    return snapshots;

} catch (IOException e) {
    throw new IOException("Error reading file: " + file.getAbsolutePath(), e);
}

}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (SnapshotReader reader = new SnapshotReader(file)) {
      while (reader.hasNext()) {
        Snapshot s = reader.read();
        if (s.getTimestamp() == null) {
          continue;
        }
        for (ProfileAnalyzeTimeRange range : timeRanges) {
          if (range.getStartTime() <= s.getTimestamp() && s.getTimestamp() <= range.getEndTime()) {
            snapshots.add(s);
            break;
          }
        }
      }
    }
    return snapshots;
  }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (RandomAccessFile raf = new RandomAccessFile(file, "r")) {
        // Read the header and verify the magic number
        byte[] header = new byte[12];
        raf.read(header);
        if (!Arrays.equals(header, ThreadSnapshot.MAGIC)) {
            throw new IOException("Invalid snapshot file: Invalid magic number");
        }

        // Read the optional header and annotation count
        int numAnnotations = raf.readInt();

        // Read the snapshot count
        int numSnapshots = raf.readInt();

        // Read the snapshots
        for (int i = 0; i < numSnapshots; i++) {
            // Read the snapshot start offset
            long startOffset = raf.readLong();

            // Seek to the snapshot start offset
            raf.seek(startOffset);

            // Read the snapshot length
            long length = raf.readLong();

            // Check if the snapshot is within the time range
            boolean withinTimeRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range.contains(startOffset)) {
                    withinTimeRange = true;
                    break;
                }
            }

            // If the snapshot is not within the time range, continue to the next snapshot
            if (!withinTimeRange) {
                continue;
            }

            // Skip the optional header and annotation count
            raf.skipBytes(numAnnotations * 20);

            // Read the snapshot thread stack trace
            byte[] stackTrace = new byte[(int)length];
            raf.read(stackTrace);

            // Add the snapshot to the list
            snapshots.add(new ThreadSnapshot(startOffset, length, stackTrace));
        }
    }
    return snapshots;
}
